def _tokenize(text: str) -> list:
    return jieba.lcut(text)


def _ngram_match(continuation: str, reference: str) -> int:
    """
    Computes the number of n-grams in the continuation that match with the reference text.

    Input-Output Arguments
    :param continuation: str, the generated text whose quality is being evaluated.
    :param reference: str, the reference text against which the continuation is compared.
    :return: int, the number of n-grams in the continuation that match with the reference text.
    """
    continuation = _tokenize(continuation)
    reference = _tokenize(reference)
    return evaluate.ngram_match(continuation, reference)


def _compute_bleu4_score(continuation: str, reference: str) -> float:
    """
    Computes the BLEU-4 score for a given continuation and reference text.

    Input-Output Arguments
    :param continuation: str, the generated text whose quality is being evaluated.
    :param reference: str, the reference text against which the continuation is compared.
    :return: float, the calculated BLEU-4 score.
