def _wait_for_file_to_exist_on_disk(
    input_dir: str, obj: parse.ParseResult, sleep_time: int = 2, timeout: int = 10
) -> Any:
    """This function checks."""
    while True:
        try:
            return os.path.join(input_dir, obj.path.lstrip("/"))
        except FileNotFoundError:
            sleep(sleep_time)
            if timeout == 0:
                raise TimeoutError
            timeout -= 1


