    return [anno for anno in annos if anno.get("bbox", None) is not None or anno.get("segmentation", None) is not None]

def _get_seg_masks(annos, image_size, mask_format):
    """
    Convert segmentation annotations to bit masks.
    """
    if mask_format == "polygon":
        masks = [polygons_to_bitmask(anno["segmentation"], image_size) for anno in annos]
    elif mask_format == "bitmask":
        masks = [BitMasks(anno["segmentation"], image_size) for anno in annos]
    else:
        raise ValueError("Unsupported mask format: {}".format(mask_format))
    return masks

def _get_keypoints(annos):
    """
    Convert keypoints annotations to a list of keypoints.
    """
    keypoints = []
    for anno in annos:
        if "keypoints" in anno:
            keypoints.append(Keypoints(anno["keypoints"]))
    return keypoints

def _get_classes(annos):
    """
    Convert class annotations to a list of class IDs.
    """
    if "category_id" in annos[0]:
        return [anno["category_id"] for anno in annos]
    else:
        return [anno["category"] for anno in annos]

def _get_boxes(annos):
    """
