def _download_file(input_dir: Dir, file_path: str, cache_dir: str) -> None:
    """This function downloads a file from a local directory to a local cache directory."""
    if input_dir.is_s3:
        _download_file_from_s3(s3, file_path, cache_dir)
    elif input_dir.is_local:
        _download_file_from_local(input_dir, file_path, cache_dir)
    elif input_dir.is_url:
        _download_file_from_url(input_dir.url, file_path, cache_dir)
    else:
        raise ValueError(f"Invalid input_dir: {input_dir}")


