def bisection_search(
    model: Model, prefix: str, idx: int, k=1, low=0, high=32, eps=1e-8
):
    # check if idx is the argmax
    num_calls = k
    if model.argmax(prefix) == idx:
        return 0, num_calls

    # initialize high
    logit_bias = {idx: high}
    while model.argmax(prefix, logit_bias) != idx:
        logit_bias[idx] *= 2
        num_calls += k
    high = logit_bias[idx]

    # improve estimate
    mid = (high + low) / 2
    while high >= low + eps:
        logit_bias[idx] = mid
        if model.argmax(prefix, logit_bias) == idx:
            high = mid
        else:
            low = mid
        mid = (high + low) / 2
        num_calls += k
    return -mid, num_calls


