def topk_search_parallel(
    model: Model,
    prefix: str,
    idx: int,
    k=1,
    high=40,
    n_jobs: int = 1,
    batch_size: int = 1000,
    max_workers: int = 1,
    logit_bias: Optional[dict[int, float]] = None,
    top_logprob: Optional[float] = None,
) -> tuple[float, int]:
    """Parallel topk search based on https://mattf1n.github.io/openlogprobs.html"""
    if logit_bias is None:
        logit_bias = {idx: high}
    if top_logprob is None:
        top_logprob = model.logprob(prefix, logit_bias)
    logit_bias[idx] = high
    logprob = model.logprob(prefix, logit_bias) - top_logprob
    if model.argmax(prefix, logit_bias) == idx:
        return logprob, 1
    else:
        if n_jobs == 1:
            return topk_search(model, prefix, idx, k, high)
        else:
            with ThreadPoolExecutor(max_workers=max_workers) as executor:
                futures = [
                    executor.submit(
                        topk_search, model, prefix, idx, k, high
                    ) for _ in range(n_jobs)
                ]
                results = [
                    future.result() for future in tqdm.tqdm(futures, total=n_jobs)
                ]
                logprob = reduce(
                    union, (logprob, *map(lambda x: x[0], results)), logprob
                )
                return logprob, sum(map(lambda x: x[1], results))


